parameters.jsCode:
// 1. Récupérer le texte renvoyé par l'IA
const raw = $json.choices[0].message.content;

// 2. Nettoyer : certains modèles entourent le JSON de ```json ... ```
const cleaned = raw.replace(/```json|```/g, '').trim();

// 3. Convertir le texte en objet JavaScript
let ai;
try {
  ai = JSON.parse(cleaned);
} catch (error) {
  throw new Error('AI answer is not valid JSON: ' + raw);
}

// 4. Récupérer les données des nœuds précédents, par leur nom
const email = $('Email Trigger (IMAP)').item.json;
const config = $('Config').item.json;

// 5. Extraire l'adresse e-mail de "Nom <adresse@domaine.com>"
const match = (email.from || '').match(/<([^>]+)>/);
const senderEmail = match ? match[1] : (email.from || '').trim();

// 6. Mode test : en test, toutes les réponses partent vers notre adresse
const replyTo = config.test_mode ? config.test_recipient : senderEmail;

// 7. Tout regrouper dans un objet propre
return {
  sender_email: senderEmail,
  reply_to: replyTo,
  test_mode: config.test_mode,
  original_subject: email.subject,
  original_body: (email.textPlain || '').slice(0, 2000),
  is_automated: ai.is_automated,
  category: ai.category,
  urgency: ai.urgency,
  sentiment: ai.sentiment,
  language: ai.language,
  summary: ai.summary,
  needs_human: ai.needs_human,
  reply_subject: ai.reply_subject,
  reply_body: ai.reply_body,
  support_email: config.support_email,
  team_email: config.team_email,
  company_name: config.company_name
};

